content.text:
    self.total_weight += delta;
    self.task[id].weight = weight;
    self.update_work(group);
}

fn set_class_raw(&mut self, id: usize, class: u64) {
    if self.task[id].class == class {
        return;
    }
    let group = self.task[id].group;
    let key = (self.dom[self.task[id].template], self.task[id].class as i64);
    self.drop_key(group, key);
    self.task[id].class = class;
    let key = (self.dom[self.task[id].template], class as i64);
    self.bump_key(group, key);
}

fn set_pin_raw(&mut self, id: usize, pinned: bool) {
    if self.task[id].pinned == pinned {
        return;
    }
    let group = self.task[id].group;
    self.task[id].pinned = pinned;
    if pinned {
        self.pins += 1;
        self.pin_in_group[group] += 1;
    } else {
        self.pins -= 1;
        self.pin_in_group[group] -= 1;
    }
}

fn set_cap_raw(&mut self, node: usize, capacity: u64) {
    let value = capacity as i64;
    if self.caps[node] == value {
        return;
    }
    self.caps[node] = value;
    self.recheck_over(node);
}

fn set_budget_raw(&mut self, group: usize, budget: u64) {
    if self.budget[group] == budget {
        return;
    }
    self.budget[group] = budget;
    self.update_work(group);
}

fn set_quota_raw(&mut self, group: usize, quota: u64) {
    if self.quota[group] == quota {
        return;
    }
    let delta = quota as i64 - self.quota[group] as i64;
    let gbase = group * self.words;
    for word_index in 0..self.words {
        let mut word = self.union_fp[gbase + word_index];
        while word != 0 {
            let bit = word.trailing_zeros() as usize;
            word &= word - 1;
            let node = word_index * 64 + bit;
            self.usage[node] += delta;
            self.recheck_over(node);
        }
    }
    self.slots += delta * self.fp_size[group];
    self.quota[group] = quota;
    self.update_work(group);
}

fn move_raw(&mut self, id: usize, group: usize) {
    if self.task[id].group == group {
        return;
    }
    let old = self.task[id].group;
    self.detach(id, old);
    self.task[id].group = group;
    self.attach(id, group);
}

fn bind_raw(&mut self, id: usize, template: usize) {
    if self.task[id].template == template {
        return;
    }
    let group = self.task[id].group;
    self.detach(id, group);
    self.task[id].template = template;
    self.attach(id, group);
}

// ------------------------------------------------------- journal layer

fn apply(&mut self, edit: Edit) {
    match edit {
        Edit::Move(id, group) => {
            if self.task[id].group != group {
                self.journal.push(Undo::Move(id, self.task[id].group));
                self.move_raw(id, group);
            }
        }
        Edit::Bind(id, template) => {
            if self.task[id].template != template {
                self.journal.push(Undo::Bind(id, self.task[id].template));
                self.bind_raw(id, template);
            }
        }
        Edit::Weight(id, weight) => {
            if self.task[id].weight != weight {
                self.journal.push(Undo::Weight(id, self.task[id].weight));
                self.set_weight_raw(id, weight);
            }
        }
        Edit::Class(id, class) => {
            if self.task[id].class != class {
                self.journal.push(Undo::Class(id, self.task[id].class));
                self.set_class_raw(id, class);
            }
        }
        Edit::Pin(id, pinned) => {
            if self.task[id].pinned != pinned {
                self.journal.push(Undo::Pin(id, self.task[id].pinned));
                self.set_pin_raw(id, pinned);
            }
        }
        Edit::Quota(group, quota) => {
            if self.quota[group] != quota {
                self.journal.push(Undo::Quota(group, self.quota[group]));
                self.set_quota_raw(group, quota);
            }
        }
        Edit::Budget(group, budget) => {
            if self.budget[group] != budget {
                self.journal.push(Undo::Budget(group, self.budget[group]));
                self.set_budget_raw(group, budget);
            }
        }
        Edit::Cap(node, capacity) => {
            if self.caps[node] != capacity as i64 {
                self.journal.push(Undo::Cap(node, self.caps[node] as u64));
                self.set_cap_raw(node, capacity);
            }
        }
    }
}

fn rollback(&mut self) {
    while let Some(entry) = self.journal.pop() {
        match entry {
            Undo::Move(id, group) => self.move_raw(id, group),
            Undo::Bind(id, template) => self.bind_raw(id, template),
            Undo::Weight(id, weight) => self.set_weight_raw(id, weight),
            Undo::Class(id, class) => self.set_class_raw(id, class),
            Undo::Pin(id, pinned) => self.set_pin_raw(id, pinned),
            Undo::Quota(group, quota) => self.set_quota_raw(group, quota),
            Undo::Budget(group, budget) => self.set_budget_raw(group, budget),
            Undo::Cap(node, capacity) => self.set_cap_raw(node, capacity),
        }
    }
}

